For $a,b\in A_+$, write $a\precsim b$ if there are $w_m\in A\otimes\mathbb K$
such that
\[
w_m^*(b\otimes e_{11})w_m\longrightarrow a\otimes e_{11}
\]
in norm. We say that \(A\) has comparison by \(\tau\) if
\begin{equation}\label{eq:factor-comparison}
\mathrm{d}_\tau(a)<\mathrm{d}_\tau(b)\ \Longrightarrow\ a\precsim b,
\qquad a,b\in A_+.
\end{equation}

\label{lem:unstabilize}
If $a,b\in A_+$ and $a\precsim b$, then for every $\eta>0$ there is
$v\in A$ such that $\left\|v^*bv-a\right\|<\eta$.

\label{lem:markov}
If $d\in A_\mathrm{sa}$ and $\varepsilon>0$, then
\begin{equation}\label{eq:markov}
\mathrm{d}_\tau((\pm d-\varepsilon)_+)
\leq\varepsilon^{-2}\left\|d\right\|_2^2.
\end{equation}
Moreover,
\begin{equation}\label{eq:truncate}
\left\|d-\bigl((d-\varepsilon)_+-(-d-\varepsilon)_+\bigr)\right\|
\leq\varepsilon.
\end{equation}

\label{fg:thm:recovery}
Let \(A\) be separable and unital with \(\mathrm{T}(A)\neq\varnothing\).
Assume \textup{(C)}, and let \(u\in A\) be a unitary such that
\begin{equation}\label{fg:eq:capacity}
\inf_{\rho\in \mathrm{T}(A)}\rho(f(u))>0
\quad\text{for every nonzero }f\in \mathrm{C}(\mathbb T)_+.
\end{equation}
Use the functions \(\psi_j\) of Section~\ref{fg:sec:bands}, and
suppose
\begin{equation}\label{fg:eq:background}
y=\sum_{j=0}^{22}\psi_j(u)b_j\psi_j(u),
\qquad b_j=b_j^*\in A.
\end{equation}
Put \(\mathcal B=\ensuremath{\mathrm{C}^*}(1,u,y)\). Assume that for every self-adjoint
contraction \(z\in A\) and every \(\eta>0\), there is a
self-adjoint contraction \(c\in\mathcal B\) with
\begin{equation}\label{fg:eq:uniform-approx}
\left\|z-c\right\|_{2,\mathrm{T}(A)}<\eta.
\end{equation}
Then \(A=\ensuremath{\mathrm{C}^*}(u(R1+h))\) for some \(h=h^*\in A\) and
\(R>\left\|h\right\|\).

\label{fg:lem:orientation}
There is a tournament on \(\mathbb Z/23\mathbb Z\) such that every
nonempty source set \(S\) of at most two labels has a label \(\ell(S)\)
with
\begin{equation}\label{fg:eq:orientation}
\ell(S)\to j\quad(j\in S),\qquad
\ell(S)\notin\{j,j-1,j+1:j\in S\}.
\end{equation}

\label{fg:lem:corner}
For every nonzero projection \(p\in D\), there is a self-adjoint
contraction \(Z\in pMp\) with \(\ensuremath{\mathrm{W}^*}(pD,Z)=pMp\).

\label{fg:prop:background}
A norm-dense \(G_\delta\) subset of \(A_\mathrm{sa}^{23}\) consists of
tuples \(\mathbf b\) for which \(y=y_{\mathbf b}\) satisfies
\begin{enumerate}[label=\textup{(\roman*)},leftmargin=*]
\item \(\tau\mapsto\tau(y)\) is injective on \(K\);
\item \(\ensuremath{\mathrm{W}^*}(u_\tau,\pi_\tau(y))=M_\tau\) for every \(\tau\in K\);
\item \(\mathcal B=\ensuremath{\mathrm{C}^*}(1,u,y)\) satisfies \eqref{fg:eq:uniform-approx}.
\end{enumerate}

\label{lem:free-word-bound}
Let \((M,\tau)=(M_0,\tau_0)*(M_1,\tau_1)\) be a free product of
finite von Neumann algebras with faithful normal tracial states.
If \(a_j\in M_{i_j}\), \(\tau(a_j)=0\), and
\(i_j\ne i_{j+1}\), then
\begin{equation}\label{eq:free-word-bound}
\left\|a_1\cdots a_n\right\|
\leq (n+1)\prod_{j=1}^n\left\|a_j\right\|_2
 +\sum_{k=1}^n\left\|a_k\right\|\prod_{j\ne k}\left\|a_j\right\|_2.
\end{equation}

\label{prop:free-product-compression}
Let \((A,\tau)=(A_0,\tau_0)*(B,\sigma)\), where the two
unital \ensuremath{\mathrm{C}^*}-algebras have faithful tracial states. Identify their
GNS images with subalgebras of \(M=\pi_\tau(A)''\), and put
\(M_0=\pi_{\tau_0}(A_0)''\). Let \(D\subseteq M_0\) be a
unital von Neumann subalgebra. If, for every \(a_0\in A_0\),
\begin{equation}\label{eq:base-compression}
\lim_{t\downarrow0}
\sup_{\substack{p\in D\ {\rm projection}\\0<\tau_0(p)\leq t}}
\left\|p\bigl(a_0-\mathbb E_D^{M_0}(a_0)\bigr)p\right\|=0,
\end{equation}
then, for every \(a\in A\),
\begin{equation}\label{eq:product-compression}
\lim_{t\downarrow0}
\sup_{\substack{p\in D\ {\rm projection}\\0<\tau(p)\leq t}}
\left\|p\bigl(a-\mathbb E_D^M(a)\bigr)p\right\|=0.
\end{equation}
